    |> filter(fn: (r) => r._measurement == "power")
    |> filter(fn: (r) => r.deviceId == "main")
    |> filter(fn: (r) => r._field == "energyUsage")
    |> sum()
    |> map(fn: (r) => ({
        r with energyUsage: r._value
    }))

