const itemColors = {
  Total: "#374151",

  // Main groups
  Chillers: "#2563EB",
  "CHW Pumps": "#7C3AED",
  "CW Pumps": "#EA580C",
  Fans: "#059669",

  // Chillers
  chiller1: "#1D4ED8",
  chiller2: "#3B82F6",
  chiller3: "#60A5FA",

  // Chilled-water pumps
  chwp1: "#6D28D9",
  chwp2: "#8B5CF6",
  chwp3: "#A78BFA",

  // Condenser-water pumps
  cwp1: "#C2410C",
  cwp2: "#F97316",
  cwp3: "#FB923C",

  // Cooling-tower fans
  ct1Fan1: "#047857",
  ct1Fan2: "#059669",
  ct2Fan1: "#0D9488",
  ct2Fan2: "#14B8A6",
  ct3Fan1: "#10B981",
  ct3Fan2: "#34D399"
};

const toName = (id) => {
  if (id.startsWith('ct')) {
    return id.replace('Fan', '-').replace('ct', 'CT')
  }
  if (id.startsWith('chwp')) {
    return id.replace('chwp', 'CHWP');
  }
  if (id.startsWith('cwp')) {
    return id.replace('cwp', 'CWP');
  }
  if (id.startsWith('chiller')) {
    return id.replace('chiller', 'Chiller ');
  }

}

try {
  // 1. Initialize persistent state management on the context object safely
  if (!context.customState) {
    context.customState = {
      currentView: 'root', // 'root' or 'drilldown'
      drillCategory: null  // Tracks which category is expanded ('Pumps', 'Fans', 'Chillers')
    };
  }

  // 2. FIXED: Correctly reference series[0] array prior to extracting fields
  const seriesData = context.panel.data.series[0];
  if (!seriesData || !seriesData.fields) {
    return {}; // Return empty if Grafana data hasn't arrived yet
  }

  const numericFields = seriesData.fields.filter(f => f.type === "number");

  const depths = [
    { depth: 0, itemStyle: { color: '#fbb4ae' }, lineStyle: { color: 'source', opacity: 0.6 } },
    { depth: 1, itemStyle: { color: '#b3cde3' }, lineStyle: { color: 'source', opacity: 0.6 } },
    { depth: 2, itemStyle: { color: '#ccebc5' }, lineStyle: { color: 'source', opacity: 0.6 } }
  ];

  let vals = [];
  let types = [];
  let devices = [];

  for (const device of numericFields) {
    const deviceId = device.name;
    vals.push(device.values[0]);
    devices.push(deviceId);
    let type = 'Chillers';
    if (deviceId.startsWith('cwp')) {
      type = 'CW Pumps';
    } else if (deviceId.startsWith('chwp')) {
      type = 'CHW Pumps';
    } else if (deviceId.endsWith('Fan1') || deviceId.endsWith('Fan2')) {
      type = 'Fans';
    }
    types.push(type)
  }

  // 3. Compute totals for parent nodes
  let totalChwPumps = 0;
  let totalCwPumps = 0;
  let totalFans = 0;
  let totalChillers = 0;

  for (let i = 0; i < types.length; i += 1) {
    if (types[i] === "Chillers") {
      totalChillers += vals[i];
    } else if (types[i] === "Fans") {
      totalFans += vals[i];
    } else if (types[i] === "CHW Pumps") {
      totalChwPumps += vals[i];
    } else {
      totalCwPumps += vals[i];
    }
  }
  const totalPower = totalChwPumps + totalCwPumps + totalFans + totalChillers;

  // 4. Build conditional nodes and links arrays based on active state
  function getData() {
    let targetNodes = [];
    let targetLinks = [];
    if (context.customState.currentView === 'root') {
      // LEVEL 1: High-level view (Total -> Categories)
      targetNodes = [
        { name: "Total", itemStyle: { color: itemColors.Total } },
        { name: "Chillers", itemStyle: { color: itemColors.Chillers } },
        { name: "CHW Pumps", itemStyle: { color: itemColors["CHW Pumps"] } },
        { name: "CW Pumps", itemStyle: { color: itemColors["CW Pumps"] } },
        { name: "Fans", itemStyle: { color: itemColors.Fans } }
      ];
      targetLinks = [
        { source: "Total", target: "CHW Pumps", value: totalChwPumps },
        { source: "Total", target: "CW Pumps", value: totalCwPumps },
        { source: "Total", target: "Fans", value: totalFans },
        { source: "Total", target: "Chillers", value: totalChillers }
      ];

      for (let i = 0; i < types.length; i += 1) {
        targetNodes.push({ name: toName(devices[i]), itemStyle: { color: itemColors[devices[i]] } });
        targetLinks.push({
          source: types[i],
          target: toName(devices[i]),
          value: vals[i],
        });
      }
    } else {
      // LEVEL 2: Drilled-down view (Category -> Specific Devices)
      const category = context.customState.drillCategory;

      // Add the single focused category parent node
      targetNodes.push({ name: category, itemStyle: { color: itemColors[category] } });

      // Add only the children matching the clicked category
      for (let i = 0; i < types.length; i += 1) {
        if (types[i] === category) {
          targetNodes.push({ name: toName(devices[i]), itemStyle: { color: itemColors[devices[i]] } });
          targetLinks.push({
            source: category,
            target: toName(devices[i]),
            value: vals[i]
          });
        }
      }
    }

    return { targetLinks, targetNodes };
  }

  function getDepths() {
    if (context.customState.currentView === 'root') {
      return depths;
    }
    return depths.filter((v, i) => i > 0).map((v, i) => {
      v.depth = i;
      return v;
    });
  }

  // 5. Handle Interactive Click Actions
  context.panel.chart.off("click");
  context.panel.chart.on("click", (params) => {
    if (params.dataType !== 'node') return;

    const clickedNode = params.name;

    if (clickedNode === 'Total' && context.customState.currentView === 'root') return;

    if (context.customState.currentView === 'root') {
      if (['CHW Pumps', 'CW Pumps', 'Fans', 'Chillers'].includes(clickedNode)) {
        context.customState.currentView = 'drilldown';
        context.customState.drillCategory = clickedNode;
        context.grafana.notifySuccess(["Drill Down", `Viewing ${clickedNode}`]);
      } else {
        return;
      }
    } else {
      if (clickedNode === context.customState.drillCategory) {
        context.customState.currentView = 'root';
        context.customState.drillCategory = null;
        context.grafana.notifySuccess(["Navigation", "Returned to Total View"]);
      } else {
        return;
      }
    }

    const { targetNodes, targetLinks } = getData();
    const options = context.panel.chart.getOption();
    options.series[0].data = targetNodes;
    options.series[0].links = targetLinks;
    options.series[0].levels = getDepths();
    context.panel.chart.setOption(options, { replaceMerge: ['series'] });
  });

  const { targetNodes: nodes, targetLinks: links } = getData();

  const localeOpt = {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  };

  // 6. Return chart option configuration
  return {
    tooltip: {
      trigger: 'item',
      triggerOn: 'mousemove',
      formatter: function (params) {
        // const val = typeof params.value === 'number' ? params.value.toFixed(2) : '0.00';
        const val = typeof params.value === 'number' ? params.value.toLocaleString('en-US', localeOpt) : '0.00';
        return `${params.name}: ${val} kWh (${(params.value / totalPower * 100).toFixed(1)}%)`;
      }
    },
    series: [
      {
        left: 40,
        right: 80,
        type: 'sankey',
        data: nodes,
        links: links,
        emphasis: { focus: 'adjacency' },
        levels: getDepths(),
        lineStyle: { curveness: 0.5 }
      }
    ]
  };
} catch (e) {
  console.error('Sankey Layout Render Error: ', e);
  return {};
}

